%[text] correlation ensemble 和Naive比较
ALB=TransferLearning.AudioLightBaseline; %[output:01070da3] %[output:05ef65e2] %[output:911ab85e] %[output:5299e2a7] %[output:1ee632fa] %[output:1e724cab] %[output:8be101a3] %[output:4cb3d08a] %[output:69c37d10] %[output:072a571b] %[output:3e221b2f] %[output:523c9660] %[output:85b0c748] %[output:4aa69047] %[output:152250cd] %[output:9be34a59] %[output:007e96e4] %[output:0d063643] %[output:4d3a2265] %[output:9fdcb825] %[output:5902bee1] %[output:4ad1133d] %[output:86258082] %[output:74ea5645] %[output:2c3d6386] %[output:81162ce1] %[output:05810d7e] %[output:6bbd8076] %[output:25e915c7] %[output:56e4a587] %[output:82ee069f] %[output:63e60047] %[output:98635814]
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
LAB=TransferLearning.LightAudioBaseline; %[output:10a54a8c] %[output:4ed09b26] %[output:86446fa4] %[output:8aeb8188] %[output:70ec6811] %[output:0480c154] %[output:252ea328] %[output:371f9e9a] %[output:75a8f022] %[output:1806e05b] %[output:868c596c] %[output:2bf98887] %[output:9d7e60cb] %[output:0bba1557] %[output:386e040b] %[output:354deb23] %[output:1d3e2f96] %[output:10e16e9a] %[output:88c50107] %[output:527e0b91]
%[text:tableOfContents]{"heading":"目录"}
%[text] # A
%[text] 相关性群体
Fig=figure; %[output:1169861a]
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='tight'); %[output:1169861a]
%[text] 学会阶段相关性群体
EnsembleA1=ALB.QueryNTATS(struct(Stimulus="AudioWater",Phase="Learned"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
EnsembleA1=ALB.QueryNTS(struct(Stimulus="AudioWater",Phase="Learned",CellUID=EnsembleA1.CellUID(max(EnsembleA1.NTATS{:,25:32},[],2)>std(EnsembleA1.NTATS{:,1:24},[],2)*3)),UniExp.Flags.ZScore,1:24,ExtraColumns="TrialRI");
EnsembleA1=sortrows(EnsembleA1{1},["TrialRI","CellUID"]);
Signal=permute(reshape(normalize(EnsembleA1.TrialSignal,2,'zscore'),[],30,width(EnsembleA1.TrialSignal)),[1,3,2]);
Correlation=sum(pagemtimes(Signal,'none',Signal,'transpose'),3);
SortIndex=UniExp.CorrelationSort(Correlation);
Correlation=Correlation(SortIndex,SortIndex);
nexttile; %[output:1169861a]

imagesc(Correlation); %[output:1169861a]
colormap(gray); %[output:1169861a]
title('Learned ensemble'); %[output:1169861a]
axis off; %[output:1169861a]
%[text] 最终阶段相关性群体
EnsembleA2=ALB.QueryNTATS(struct(Stimulus="LightWater",Phase="Final"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
EnsembleA2=ALB.QueryNTS(struct(Stimulus="AudioWater",Phase="Learned",CellUID=EnsembleA2.CellUID(max(EnsembleA2.NTATS{:,25:32},[],2)>std(EnsembleA2.NTATS{:,1:24},[],2)*3)),UniExp.Flags.ZScore,1:24,ExtraColumns="TrialRI");
EnsembleA2=sortrows(EnsembleA2{1},["TrialRI","CellUID"]);
Signal=permute(reshape(normalize(EnsembleA2.TrialSignal,2,'zscore'),[],30,width(EnsembleA2.TrialSignal)),[1,3,2]);
Correlation=sum(pagemtimes(Signal,'none',Signal,'transpose'),3);
SortIndex=UniExp.CorrelationSort(Correlation);
Correlation=Correlation(SortIndex,SortIndex);
nexttile; %[output:1169861a]
imagesc(Correlation); %[output:1169861a]
colormap(gray); %[output:1169861a]
title('Final ensemble'); %[output:1169861a]
axis off; %[output:1169861a]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:1169861a]
print(Fig,TransferLearning.ProjectPath('Fig3A.svg'),'-dsvg'); %[output:1169861a]
%%
%[text] # B
%[text] 各群体交织率
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(TransferLearning.ProjectPath('查询表.xlsx'),'Fig3B'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:1fc8aeb7]
%%
EnsembleLogical=max(GroupNtats.NTATS(:,25:32,:),[],2)>std(GroupNtats.NTATS(:,1:24,:),[],2).*3;
VennTensor(2,1,1)=mean(EnsembleLogical.Naive);
VennTensor(1,2,1)=mean(EnsembleLogical.Learned);
VennTensor(1,1,2)=mean(EnsembleLogical.Final);
VennTensor(2,2,1)=mean(EnsembleLogical.Naive & EnsembleLogical.Learned);
VennTensor(2,1,2)=mean(EnsembleLogical.Naive & EnsembleLogical.Final);
VennTensor(1,2,2)=mean(EnsembleLogical.Learned & EnsembleLogical.Final);
VennTensor(2,2,2)=mean(EnsembleLogical.Naive & EnsembleLogical.Learned & EnsembleLogical.Final);
%%
Fig=figure; %[output:8c15524c]
Circles=MATLAB.Graphics.Venn(VennTensor,table([1,0.3191,1;1,1,0;0,1,1],[1/3;1/3;1/3],'VariableNames',["FaceColor","FaceAlpha"]),MATLAB.SignificantFixedpoint(VennTensor*100,2)+"%"); %[output:8c15524c]
axis off; %[output:8c15524c]
title('Ensembles overlap'); %[output:8c15524c]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:8c15524c]
legend(Circles,["Naive 🔊💧","Learned 🔊💧","Final 💡💧"],Location=MATLAB.Graphics.OptimizedLegendLocation(Circles)); %[output:8c15524c]
print(Fig,TransferLearning.ProjectPath('Fig3B.svg'),'-dsvg'); %[output:8c15524c]

